/// One monitor.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Monitor {
    /// The OS's identifier.
    pub id: u32,
    /// Its bounds.
    pub bounds: Rect,
    /// Its work area.
    pub work_area: Rect,
    /// The scale as the rational p/q (GR-D17): the numerator.
    pub scale_num: u32,
    /// The denominator.
    pub scale_den: u32,
    /// Refresh rate in millihertz.
    pub refresh_mhz: u32,
    /// The primary monitor.
    pub primary: bool,
}

impl Wire for Monitor {
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u32 as Wire>::MIN_LEN),
                            <Rect as Wire>::MIN_LEN,
                        ),
                        <Rect as Wire>::MIN_LEN,
                    ),
                    <u32 as Wire>::MIN_LEN,
                ),
                <u32 as Wire>::MIN_LEN,
            ),
            <u32 as Wire>::MIN_LEN,
        ),
        <bool as Wire>::MIN_LEN,
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u32 as Wire>::MAX_LEN),
                            <Rect as Wire>::MAX_LEN,
                        ),
                        <Rect as Wire>::MAX_LEN,
                    ),
                    <u32 as Wire>::MAX_LEN,
                ),
                <u32 as Wire>::MAX_LEN,
            ),
            <u32 as Wire>::MAX_LEN,
        ),
        <bool as Wire>::MAX_LEN,
    );
    fn encode(&self, w: &mut Writer) {
        self.id.encode(w);
        self.bounds.encode(w);
        self.work_area.encode(w);
        self.scale_num.encode(w);
        self.scale_den.encode(w);
        self.refresh_mhz.encode(w);
        self.primary.encode(w);
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        Ok(Self {
            id: Wire::decode(r)?,
            bounds: Wire::decode(r)?,
            work_area: Wire::decode(r)?,
            scale_num: Wire::decode(r)?,
            scale_den: Wire::decode(r)?,
            refresh_mhz: Wire::decode(r)?,
            primary: Wire::decode(r)?,
        })
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <u32 as Wire>::validate(r)?;
        <Rect as Wire>::validate(r)?;
        <Rect as Wire>::validate(r)?;
        <u32 as Wire>::validate(r)?;
        <u32 as Wire>::validate(r)?;
        <u32 as Wire>::validate(r)?;
        <bool as Wire>::validate(r)?;
        Ok(())
    }
}

