/// The instruction set.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Isa {
    /// x86-64 (`X8664`: the generator takes PascalCase only).
    X8664,
    /// AArch64.
    Aarch64,
    /// RISC-V 64.
    Riscv64,
    /// Another.
    Other,
}

impl Wire for Isa {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::X8664 => {
                0u32.encode(w);
            }
            Self::Aarch64 => {
                1u32.encode(w);
            }
            Self::Riscv64 => {
                2u32.encode(w);
            }
            Self::Other => {
                3u32.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::X8664),
            1 => Ok(Self::Aarch64),
            2 => Ok(Self::Riscv64),
            3 => Ok(Self::Other),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => Ok(()),
            1 => Ok(()),
            2 => Ok(()),
            3 => Ok(()),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = 4;
    const MAX_LEN: usize = 4;
}

#[cfg(test)]
impl crate::sample::Sample for Isa {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        match g.below(4) {
            0 => Self::X8664,
            1 => Self::Aarch64,
            2 => Self::Riscv64,
            _ => Self::Other,
        }
    }
}

