/// A power input. The three deadline inputs carry a reply token: the
/// broker answers with `OsCommand.reply` before the deadline, or the
/// per-OS module answers the OS with the platform's default at 80% of it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PowerEvent {
    /// The current state.
    State {
        /// On AC power.
        ac: Tri,
        /// Battery saver or Low Power Mode.
        saver: Tri,
        /// The thermal state.
        thermal: Thermal,
        /// The screen is locked.
        locked: Tri,
    },
    /// The machine will sleep.
    WillSleep {
        /// Answer with this token.
        token: u64,
        /// Milliseconds the OS allows.
        deadline_ms: u32,
    },
    /// The session will end.
    SessionEnd {
        /// Answer with this token.
        token: u64,
        /// Milliseconds the OS allows.
        deadline_ms: u32,
    },
    /// The OS asks whether the session may end.
    QueryEnd {
        /// Answer with this token.
        token: u64,
        /// Milliseconds the OS allows.
        deadline_ms: u32,
    },
    /// The machine woke.
    DidWake,
}

impl Wire for PowerEvent {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::State {
                ac,
                saver,
                thermal,
                locked,
            } => {
                0u32.encode(w);
                ac.encode(w);
                saver.encode(w);
                thermal.encode(w);
                locked.encode(w);
            }
            Self::WillSleep { token, deadline_ms } => {
                1u32.encode(w);
                token.encode(w);
                deadline_ms.encode(w);
            }
            Self::SessionEnd { token, deadline_ms } => {
                2u32.encode(w);
                token.encode(w);
                deadline_ms.encode(w);
            }
            Self::QueryEnd { token, deadline_ms } => {
                3u32.encode(w);
                token.encode(w);
                deadline_ms.encode(w);
            }
            Self::DidWake => {
                4u32.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::State {
                ac: Wire::decode(r)?,
                saver: Wire::decode(r)?,
                thermal: Wire::decode(r)?,
                locked: Wire::decode(r)?,
            }),
            1 => Ok(Self::WillSleep {
                token: Wire::decode(r)?,
                deadline_ms: Wire::decode(r)?,
            }),
            2 => Ok(Self::SessionEnd {
                token: Wire::decode(r)?,
                deadline_ms: Wire::decode(r)?,
            }),
            3 => Ok(Self::QueryEnd {
                token: Wire::decode(r)?,
                deadline_ms: Wire::decode(r)?,
            }),
            4 => Ok(Self::DidWake),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => {
                <Tri as Wire>::validate(r)?;
                <Tri as Wire>::validate(r)?;
                <Thermal as Wire>::validate(r)?;
                <Tri as Wire>::validate(r)?;
                Ok(())
            }
            1 => {
                <u64 as Wire>::validate(r)?;
                <u32 as Wire>::validate(r)?;
                Ok(())
            }
            2 => {
                <u64 as Wire>::validate(r)?;
                <u32 as Wire>::validate(r)?;
                Ok(())
            }
            3 => {
                <u64 as Wire>::validate(r)?;
                <u32 as Wire>::validate(r)?;
                Ok(())
            }
            4 => Ok(()),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_min(
                hg_ipc::wire::len_min(
                    hg_ipc::wire::len_min(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(
                                hg_ipc::wire::len_add(
                                    hg_ipc::wire::len_add(0, <Tri as Wire>::MIN_LEN),
                                    <Tri as Wire>::MIN_LEN,
                                ),
                                <Thermal as Wire>::MIN_LEN,
                            ),
                            <Tri as Wire>::MIN_LEN,
                        ),
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u64 as Wire>::MIN_LEN),
                            <u32 as Wire>::MIN_LEN,
                        ),
                    ),
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(0, <u64 as Wire>::MIN_LEN),
                        <u32 as Wire>::MIN_LEN,
                    ),
                ),
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <u64 as Wire>::MIN_LEN),
                    <u32 as Wire>::MIN_LEN,
                ),
            ),
            0,
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_max(
                    hg_ipc::wire::len_max(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(
                                hg_ipc::wire::len_add(
                                    hg_ipc::wire::len_add(0, <Tri as Wire>::MAX_LEN),
                                    <Tri as Wire>::MAX_LEN,
                                ),
                                <Thermal as Wire>::MAX_LEN,
                            ),
                            <Tri as Wire>::MAX_LEN,
                        ),
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                            <u32 as Wire>::MAX_LEN,
                        ),
                    ),
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                        <u32 as Wire>::MAX_LEN,
                    ),
                ),
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                    <u32 as Wire>::MAX_LEN,
                ),
            ),
            0,
        ),
    );
}

