pub enum QueryKind {
    /// `default_status`.
    DefaultStatus,
    /// `settings`.
    Settings,
    /// `locale`.
    Locale,
    /// `time_zone`.
    TimeZone,
    /// `hardware`.
    Hardware,
    /// `displays`.
    Displays,
    /// `power`.
    Power,
}

impl Wire for QueryKind {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::DefaultStatus => {
                0u32.encode(w);
            }
            Self::Settings => {
                1u32.encode(w);
            }
            Self::Locale => {
                2u32.encode(w);
            }
            Self::TimeZone => {
                3u32.encode(w);
            }
            Self::Hardware => {
                4u32.encode(w);
            }
            Self::Displays => {
                5u32.encode(w);
            }
            Self::Power => {
                6u32.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::DefaultStatus),
            1 => Ok(Self::Settings),
            2 => Ok(Self::Locale),
            3 => Ok(Self::TimeZone),
            4 => Ok(Self::Hardware),
            5 => Ok(Self::Displays),
            6 => Ok(Self::Power),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => Ok(()),
            1 => Ok(()),
            2 => Ok(()),
            3 => Ok(()),
            4 => Ok(()),
            5 => Ok(()),
            6 => Ok(()),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = 4;
    const MAX_LEN: usize = 4;
}

