/// Whose registration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RegistrationOwner {
    /// The browser itself.
    Browser,
    /// An installed web app.
    App {
        /// Its id.
        app_id: hg_ipc::BoundedString<256>,
    },
}

impl Wire for RegistrationOwner {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Browser => {
                0u32.encode(w);
            }
            Self::App { app_id } => {
                1u32.encode(w);
                app_id.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::Browser),
            1 => Ok(Self::App {
                app_id: Wire::decode(r)?,
            }),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => Ok(()),
            1 => {
                <hg_ipc::BoundedString<256> as Wire>::validate(r)?;
                Ok(())
            }
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            0,
            hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<256> as Wire>::MIN_LEN),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            0,
            hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<256> as Wire>::MAX_LEN),
        ),
    );
}

