/// What a handler registration covers.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HandlerTarget {
    /// A URL scheme.
    Scheme {
        /// The scheme.
        scheme: hg_ipc::BoundedString<64>,
    },
    /// A MIME type.
    Mime {
        /// The type.
        mime: hg_ipc::BoundedString<256>,
    },
    /// A file extension.
    Extension {
        /// The extension.
        extension: hg_ipc::BoundedString<64>,
    },
}

impl Wire for HandlerTarget {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Scheme { scheme } => {
                0u32.encode(w);
                scheme.encode(w);
            }
            Self::Mime { mime } => {
                1u32.encode(w);
                mime.encode(w);
            }
            Self::Extension { extension } => {
                2u32.encode(w);
                extension.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::Scheme {
                scheme: Wire::decode(r)?,
            }),
            1 => Ok(Self::Mime {
                mime: Wire::decode(r)?,
            }),
            2 => Ok(Self::Extension {
                extension: Wire::decode(r)?,
            }),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => {
                <hg_ipc::BoundedString<64> as Wire>::validate(r)?;
                Ok(())
            }
            1 => {
                <hg_ipc::BoundedString<256> as Wire>::validate(r)?;
                Ok(())
            }
            2 => {
                <hg_ipc::BoundedString<64> as Wire>::validate(r)?;
                Ok(())
            }
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_min(
                hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<64> as Wire>::MIN_LEN),
                hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<256> as Wire>::MIN_LEN),
            ),
            hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<64> as Wire>::MIN_LEN),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<64> as Wire>::MAX_LEN),
                hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<256> as Wire>::MAX_LEN),
            ),
            hg_ipc::wire::len_add(0, <hg_ipc::BoundedString<64> as Wire>::MAX_LEN),
        ),
    );
}

