/// The OS to the broker: every OS-sourced value, recorded at the
/// `OsPort` boundary.
///
/// Interface `os.OsInput`: free, capacity 1024, overflow `drop`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OsInput {
    /// A launch: a decoded IZLH request or an OS-delivered open,
    /// normalised to one record.
    Launch {
        /// The record.
        request: LaunchRequest,
    },
    /// Who opens each web type.
    DefaultStatus {
        /// The query this answers, if any.
        call: Option<u64>,
        /// One entry per type read.
        types: hg_ipc::BoundedVec<TypeDefault, 7>,
    },
    /// Appearance and accessibility settings (a superset of AX 6.11's).
    Settings {
        /// The query this answers, if any.
        call: Option<u64>,
        /// The values.
        values: SettingsValues,
    },
    /// Languages and regional formats.
    Locale {
        /// The query this answers, if any.
        call: Option<u64>,
        /// The values.
        values: LocaleValues,
    },
    /// The time zone, at start and on every change.
    TimeZone {
        /// The query this answers, if any.
        call: Option<u64>,
        /// The zone id.
        zone: hg_ipc::BoundedString<64>,
    },
    /// The hardware class.
    Hardware {
        /// The query this answers, if any.
        call: Option<u64>,
        /// Logical cores.
        logical_cores: u16,
        /// Memory, in GiB, rounded down.
        memory_gib: u16,
        /// The instruction set.
        isa: Isa,
    },
    /// The monitors.
    Displays {
        /// The query this answers, if any.
        call: Option<u64>,
        /// Every monitor.
        monitors: hg_ipc::BoundedVec<Monitor, 16>,
    },
    /// Power state and the power deadline inputs.
    Power {
        /// The query this answers, if any.
        call: Option<u64>,
        /// The event.
        event: PowerEvent,
    },
}

