impl OsInput {
    /// Checks that `bytes` are one valid message, allocating nothing.
    ///
    /// # Errors
    /// [`BadMessage`] if they are not.
    pub fn validate_bytes(bytes: &[u8]) -> Result<(), BadMessage> {
        let mut r = Reader::new(bytes);
        match u16::decode(&mut r)? {
            0 => Self::validate_launch(&mut r)?,
            1 => Self::validate_default_status(&mut r)?,
            2 => Self::validate_settings(&mut r)?,
            3 => Self::validate_locale(&mut r)?,
            4 => Self::validate_time_zone(&mut r)?,
            5 => Self::validate_hardware(&mut r)?,
            6 => Self::validate_displays(&mut r)?,
            7 => Self::validate_power(&mut r)?,
            _ => return Err(BadMessage::UnknownOrdinal),
        }
        r.finish()
    }
}

impl hg_ipc::Interface for OsInput {
    const INFO: hg_ipc::InterfaceInfo = Self::INFO;
    fn into_wire(self) -> (Vec<u8>, Vec<hg_ipc::Handle>) {
        let mut w = Writer::new();
        match self {
            Self::Launch { request } => {
                0u16.encode(&mut w);
                Self::encode_launch(&mut w, &request);
            }
            Self::DefaultStatus { call, types } => {
                1u16.encode(&mut w);
                Self::encode_default_status(&mut w, &call, &types);
            }
            Self::Settings { call, values } => {
                2u16.encode(&mut w);
                Self::encode_settings(&mut w, &call, &values);
            }
            Self::Locale { call, values } => {
                3u16.encode(&mut w);
                Self::encode_locale(&mut w, &call, &values);
            }
            Self::TimeZone { call, zone } => {
                4u16.encode(&mut w);
                Self::encode_time_zone(&mut w, &call, &zone);
            }
            Self::Hardware {
                call,
                logical_cores,
                memory_gib,
                isa,
            } => {
                5u16.encode(&mut w);
                Self::encode_hardware(&mut w, &call, &logical_cores, &memory_gib, &isa);
            }
            Self::Displays { call, monitors } => {
                6u16.encode(&mut w);
                Self::encode_displays(&mut w, &call, &monitors);
            }
            Self::Power { call, event } => {
                7u16.encode(&mut w);
                Self::encode_power(&mut w, &call, &event);
            }
        }
        (w.into_bytes(), Vec::new())
    }
    fn from_wire(
        bytes: &[u8],
        handles: Vec<hg_ipc::Handle>,
        ipc: &std::sync::Arc<dyn hg_ipc::Ipc>,
    ) -> Result<Self, BadMessage> {
        let _ = ipc;
        // Every check before any decoding: the bytes by the validator,
        // which allocates nothing, then the handles' kinds (IPC-R1).
        Self::validate_bytes(bytes)?;
        let mut r = Reader::new(bytes);
        let msg = match u16::decode(&mut r)? {
            0 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (request,) = Self::decode_launch(&mut r)?;
                Self::Launch { request }
            }
            1 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, types) = Self::decode_default_status(&mut r)?;
                Self::DefaultStatus { call, types }
            }
            2 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, values) = Self::decode_settings(&mut r)?;
                Self::Settings { call, values }
            }
            3 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, values) = Self::decode_locale(&mut r)?;
                Self::Locale { call, values }
            }
            4 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, zone) = Self::decode_time_zone(&mut r)?;
                Self::TimeZone { call, zone }
            }
            5 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, logical_cores, memory_gib, isa) = Self::decode_hardware(&mut r)?;
                Self::Hardware {
                    call,
                    logical_cores,
                    memory_gib,
                    isa,
                }
            }
            6 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, monitors) = Self::decode_displays(&mut r)?;
                Self::Displays { call, monitors }
            }
            7 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (call, event) = Self::decode_power(&mut r)?;
                Self::Power { call, event }
            }
            _ => return Err(BadMessage::UnknownOrdinal),
        };
        r.finish()?;
        Ok(msg)
    }
}

impl hg_ipc::FreeInterface for OsInput {}

/// Receives `os.OsInput`'s messages, each already checked. An `Err`
/// closes the endpoint and reports the sender (IPC-R5).
pub trait OsInputHandler {
    /// A launch: a decoded IZLH request or an OS-delivered open,
    /// normalised to one record.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn launch(&mut self, request: LaunchRequest) -> Result<(), OsFrameError>;
    /// Who opens each web type.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn default_status(
        &mut self,
        call: Option<u64>,
        types: hg_ipc::BoundedVec<TypeDefault, 7>,
    ) -> Result<(), OsFrameError>;
    /// Appearance and accessibility settings (a superset of AX 6.11's).
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn settings(&mut self, call: Option<u64>, values: SettingsValues) -> Result<(), OsFrameError>;
    /// Languages and regional formats.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn locale(&mut self, call: Option<u64>, values: LocaleValues) -> Result<(), OsFrameError>;
    /// The time zone, at start and on every change.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn time_zone(
        &mut self,
        call: Option<u64>,
        zone: hg_ipc::BoundedString<64>,
    ) -> Result<(), OsFrameError>;
    /// The hardware class.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn hardware(
        &mut self,
        call: Option<u64>,
        logical_cores: u16,
        memory_gib: u16,
        isa: Isa,
    ) -> Result<(), OsFrameError>;
    /// The monitors.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn displays(
        &mut self,
        call: Option<u64>,
        monitors: hg_ipc::BoundedVec<Monitor, 16>,
    ) -> Result<(), OsFrameError>;
    /// Power state and the power deadline inputs.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn power(&mut self, call: Option<u64>, event: PowerEvent) -> Result<(), OsFrameError>;
}

impl OsInput {
    /// Passes this message to its handler method.
    ///
    /// # Errors
    /// The handler's.
    pub fn dispatch<H: OsInputHandler + ?Sized>(self, h: &mut H) -> Result<(), OsFrameError> {
        match self {
            Self::Launch { request } => h.launch(request),
            Self::DefaultStatus { call, types } => h.default_status(call, types),
            Self::Settings { call, values } => h.settings(call, values),
            Self::Locale { call, values } => h.locale(call, values),
            Self::TimeZone { call, zone } => h.time_zone(call, zone),
            Self::Hardware {
                call,
                logical_cores,
                memory_gib,
                isa,
            } => h.hardware(call, logical_cores, memory_gib, isa),
            Self::Displays { call, monitors } => h.displays(call, monitors),
            Self::Power { call, event } => h.power(call, event),
        }
    }
}

